  "Financial settings could not be saved.": { "Türkçe": "Finansal ayarlar kaydedilemedi.", "Deutsch": "Finanzeinstellungen konnten nicht gespeichert werden.", "Français": "Impossible d'enregistrer les paramètres financiers.", "Italiano": "Impossibile salvare le impostazioni finanziarie.", "Español (Spanish)": "No se pudieron guardar los ajustes financieros.", "Português": "Não foi possível guardar as definições financeiras.", "Русский (Russian)": "Не удалось сохранить финансовые настройки.", "日本語 (Japanese)": "財務設定を保存できませんでした。", "中文 (Chinese)": "无法保存财务设置。", "العربية (Arabic)": "تعذّر حفظ الإعدادات المالية.", "हिन्दी (Hindi)": "वित्तीय सेटिंग्स सेव नहीं हो सकीं।" },
  "Financial settings saved.": { "Türkçe": "Finansal ayarlar kaydedildi.", "Deutsch": "Finanzeinstellungen gespeichert.", "Français": "Paramètres financiers enregistrés.", "Italiano": "Impostazioni finanziarie salvate.", "Español (Spanish)": "Ajustes financieros guardados.", "Português": "Definições financeiras guardadas.", "Русский (Russian)": "Финансовые настройки сохранены.", "日本語 (Japanese)": "財務設定を保存しました。", "中文 (Chinese)": "财务设置已保存。", "العربية (Arabic)": "تم حفظ الإعدادات المالية.", "हिन्दी (Hindi)": "वित्तीय सेटिंग्स सेव हो गईं।" },
  "Follow-up": { "Türkçe": "Takip", "Deutsch": "Nachfassen", "Français": "Relance", "Italiano": "Follow-up", "Español (Spanish)": "Seguimiento", "Português": "Acompanhamento", "Русский (Russian)": "Напоминание", "日本語 (Japanese)": "フォローアップ", "中文 (Chinese)": "跟进", "العربية (Arabic)": "المتابعة", "हिन्दी (Hindi)": "फ़ॉलो-अप" },
  "Forward to…": { "Türkçe": "Şuna ilet…", "Deutsch": "Weiterleiten an…", "Français": "Transférer à…", "Italiano": "Inoltra a…", "Español (Spanish)": "Reenviar a…", "Português": "Reencaminhar para…", "Русский (Russian)": "Переслать в…", "日本語 (Japanese)": "転送先…", "中文 (Chinese)": "转发到…", "العربية (Arabic)": "إعادة توجيه إلى…", "हिन्दी (Hindi)": "इन्हें अग्रेषित…" },
